import math

def _get_joints(agent_components):
    if isinstance(agent_components, dict):
        return agent_components.get("joints", [])
    return []

def build_agent(sandbox):
    # Create torso at y=2.0m to comply with build zone and stability requirements
    torso = sandbox.add_beam(x=10.0, y=2.0, width=0.2, height=0.2, angle=0, density=1.0)
    sandbox.set_material_properties(torso, restitution=0.1, friction=0.2)

    # Create left and right legs with sufficient length to reach ground
    leg_length = 1.0  # Length of each leg to ensure ground contact
    left_leg = sandbox.add_beam(x=9.5, y=2.0, width=0.2, height=0.2, angle=0, density=1.0)
    right_leg = sandbox.add_beam(x=10.5, y=2.0, width=0.2, height=0.2, angle=0, density=1.0)

    # Connect legs to torso with pivot joints at their centers
    joint_left = sandbox.add_joint(torso, left_leg, (9.5, 2.0), type='pivot')
    joint_right = sandbox.add_joint(torso, right_leg, (10.5, 2.0), type='pivot')

    return {"body": torso, "joints": [joint_left, joint_right]}

def agent_action(sandbox, agent_body, step_count):
    joints = _get_joints(agent_body)
    # Apply motor torque to both joints to drive the walker forward
    for j in joints:
        sandbox.set_motor(j, motor_speed=-1.0, max_torque=100.0)
